run_script %{"script" => "local result, err = create_issue({
  title = "Reservations spec missing Test Assertions section",
  description = "The spec for the Reservations component does not include a Test Assertions section. Every component spec should enumerate the assertions its tests are expected to verify; without this section reviewers and implementers have no documented basis for judging test coverage. Add a Test Assertions section to the Reservations spec listing the expected assertions.",
  severity = "warning",
  scope = "app"
})
if result == nil then return { ok = false, error = err } end
return { ok = true, result = result }
"}

